		allowedSlots: []string{slotAName},
		mdas: MDAS{
			{Slot: 1, Type: "s36-100gb-qsfp28"},
		},
	},
	"ixr-r6": {
		cardType:     "iom-ixr-r6",
		allowedSlots: []string{slotAName, slotBName},
		mdas: MDAS{
