// componentCfgLine represents one SR OS config line for a component (card, sfm, xiom, mda).
// Adding a new component type = add a Kind and a case in String().
type componentCfgLine struct {
	Kind     string // "card", "sfm", "xiom", "xiomMda", "mda"
	Slot     string
	Type     string
	XiomSlot int
	MdaSlot  int
}

// String returns the SR OS CLI config line for this component.
func (l componentCfgLine) String() string {
	switch l.Kind {
	case "card":
		return fmt.Sprintf("/configure card %s card-type %s admin-state enable\n", l.Slot, l.Type)
	case "sfm":
		return fmt.Sprintf("/configure sfm %s sfm-type %s admin-state enable\n", l.Slot, l.Type)
	case "xiom":
		return fmt.Sprintf("/configure card %s xiom x%d xiom-type %s admin-state enable\n",
			l.Slot, l.XiomSlot, l.Type)
	case "xiomMda":
		return fmt.Sprintf("/configure card %s xiom x%d mda %d mda-type %s admin-state enable\n",
			l.Slot, l.XiomSlot, l.MdaSlot, l.Type)
	case "mda":
		return fmt.Sprintf("/configure card %s mda %d mda-type %s admin-state enable\n",
			l.Slot, l.MdaSlot, l.Type)
	default:
		return ""
	}
}

// buildComponentCfgLines turns root components into a slice of config lines (card, sfm, xiom,
// xiomMda, mda).
// CPM slots (A, B) are skipped. Components without Type are skipped (caller may log).
func buildComponentCfgLines(components []*Component, sfm string) []componentCfgLine {
	var lines []componentCfgLine
	for _, component := range components {
		slot := strings.ToUpper(strings.TrimSpace(component.Slot))
		if slot == slotAName || slot == slotBName {
			continue
		}
		if component.Type == "" {
			continue
		}
		lines = append(lines, componentCfgLine{Kind: "card", Slot: slot, Type: component.Type})
		if sfm != "" {
			lines = append(lines, componentCfgLine{Kind: "sfm", Slot: slot, Type: sfm})
		}
		for _, xiom := range component.XIOM {
			if xiom.Type != "" {
				lines = append(
					lines,
					componentCfgLine{
						Kind:     "xiom",
						Slot:     slot,
						Type:     xiom.Type,
						XiomSlot: xiom.Slot,
					},
				)
			}
			for _, mda := range xiom.MDA {
				if mda.Type != "" {
					lines = append(lines, componentCfgLine{
						Kind: "xiomMda", Slot: slot, Type: mda.Type,
						XiomSlot: xiom.Slot, MdaSlot: mda.Slot,
					})
				}
			}
		}
		for _, mda := range component.MDA {
			if mda.Type != "" {
				lines = append(
					lines,
					componentCfgLine{Kind: "mda", Slot: slot, Type: mda.Type, MdaSlot: mda.Slot},
				)
			}
		}
	}
	return lines
}

func buildIntegratedComponentCfgLines(nodeType string, override *Component) []componentCfgLine {
	component, ok := integratedSrosDefaultComponents[canonicalSrosNodeType(nodeType)]
	if !ok {
		return nil
	}
	if override == nil {
		override = &Component{}
	}

	defaultMdas := component.mdas

	if len(override.XIOM) > 0 {
		defaultMdas = nil
	}

	card := &Component{
		Slot: integratedSrosCardSlot,
		Type: component.cardType,
		XIOM: override.XIOM,
		MDA:  mergeIntegratedMdas(defaultMdas, override.MDA),
	}

	return buildComponentCfgLines([]*Component{card}, "")
}

func mergeIntegratedMdas(defaults, overrides MDAS) MDAS {
	bySlot := map[int]string{}
	for _, mda := range slices.Concat(defaults, overrides) {
		if mda.Slot > 0 && mda.Type != "" {
			bySlot[mda.Slot] = mda.Type
		}
	}

	slots := slices.Sorted(maps.Keys(bySlot))
	mdas := make(MDAS, 0, len(slots))
	for _, slot := range slots {
		mdas = append(mdas, MDA{Slot: slot, Type: bySlot[slot]})
	}
	return mdas
}

func canonicalSrosNodeType(nodeType string) string {
	return strings.ToLower(strings.TrimSpace(nodeType))
}

func integratedSrosDefault(nodeType string) (integratedSrosDefaultComponent, bool) {
	component, ok := integratedSrosDefaultComponents[canonicalSrosNodeType(nodeType)]
	return component, ok
}

func isIntegratedSrosNodeType(nodeType string) bool {
	_, ok := integratedSrosDefault(nodeType)
	return ok
}

func integratedSrosAllowedSlots(nodeType string) []string {
	component, ok := integratedSrosDefault(nodeType)
	if !ok || len(component.allowedSlots) == 0 {
		return []string{slotAName}
	}
	return component.allowedSlots
}

func isRedundantIntegratedSrosComponents(nodeType string, components []*Component) bool {
	if !isIntegratedSrosNodeType(nodeType) || len(components) < 2 {
		return false
	}
	for _, c := range components {
		if strings.TrimSpace(c.Slot) == "" || !integratedSrosSlotAllowed(nodeType, c.Slot) {
			return false
		}
	}
	return true
}

func integratedSrosSlotAllowed(nodeType, slot string) bool {
	slot = strings.ToUpper(strings.TrimSpace(slot))
	if slot == "" {
		slot = standaloneSlotName
	}
	return slices.Contains(integratedSrosAllowedSlots(nodeType), slot)
}

func (n *sros) generateComponentConfig() string {
	if !n.kindSpecificCfg().GenComponentConfig {
		return ""
	}
	if n.isConfigClassic() {
		return ""
	}

	if isIntegratedSrosNodeType(n.Cfg.NodeType) {
		return n.generateIntegratedComponentConfig()
	}

	components := n.rootComponents
	if len(components) == 0 {
		return ""
	}

	for _, c := range components {
		slot := strings.ToUpper(strings.TrimSpace(c.Slot))
		if slot == slotAName || slot == slotBName {
			continue
		}
		if c.Type == "" {
			log.Warn(
				"SR-SIM node has no type set for component in slot, skipping component SR OS config generation.",
				"node",
				n.Cfg.ShortName,
				"slot",
				slot,
			)
		}
	}

	lines := buildComponentCfgLines(n.componentsForConfig(components), n.componentSFM())
	return n.componentConfigFromLines(lines)
}

// hardwareEnv is the topology env, which overrides component type, XIOM, and MDA.
// Nodes that have not been through Init expose that env on Cfg.Env.
func (n *sros) hardwareEnv() map[string]string {
	if n.userEnv != nil {
		return n.userEnv
	}
	return n.Cfg.Env
}

// componentSFM is the SFM used in generated config. NOKIA_SROS_SFM overrides the sfm key.
func (n *sros) componentSFM() string {
	if sfm := n.hardwareEnv()[envNokiaSrosSFM]; sfm != "" {
		return sfm
	}
	return n.kindSpecificCfg().SFM
}

// componentForConfig clones c and applies per-component env, then node env.
func (n *sros) componentForConfig(c *Component) *Component {
	out := cloneComponent(c)
	applyHardwareEnv(out, out.Env)
	applyHardwareEnv(out, n.hardwareEnv())
	return out
}

func (n *sros) componentsForConfig(components []*Component) []*Component {
	out := make([]*Component, len(components))
	for i, c := range components {
		out[i] = n.componentForConfig(c)
	}
	return out
}

func (n *sros) componentConfigFromLines(lines []componentCfgLine) string {
	powerConfig := n.generatePowerConfig()
	if len(lines) == 0 && powerConfig == "" {
		return ""
	}

	var config strings.Builder
	for _, l := range lines {
		config.WriteString(l.String())
	}
	config.WriteString(powerConfig)
	return config.String()
}

func (n *sros) generateIntegratedComponentConfig() string {
	card := strings.TrimSpace(n.Cfg.Env[envNokiaSrosCard])
	if card != "" {
		log.Info(
			"Card type override set on integrated chassis type, skipping component SR OS config generation",
			"node",
			n.Cfg.ShortName,
			"type",
			n.Cfg.NodeType,
			"card",
			card,
		)
		return ""
	}

	lines := buildIntegratedComponentCfgLines(
		n.Cfg.NodeType,
		n.componentForConfig(n.integratedComponentOverride()),
	)
	return n.componentConfigFromLines(lines)
}

// integratedComponentOverride returns the component that overrides the integrated defaults:
// the single component of a standalone node, or the component matching the slot of a
// redundant CPM node.
func (n *sros) integratedComponentOverride() *Component {
	if n.rootCtrName == "" {
		if len(n.kindSpecificCfg().Components) == 1 {
			return n.kindSpecificCfg().Components[0]
		}
		return nil
	}

	slot := n.Cfg.Env[envNokiaSrosSlot]
	for _, c := range n.rootComponents {
		if strings.EqualFold(strings.TrimSpace(c.Slot), slot) {
			return c
		}
	}
	return nil
}

package sros

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	clabutils "github.com/srl-labs/containerlab/utils"

	"github.com/beevik/etree"
	"github.com/charmbracelet/log"
	"golang.org/x/mod/semver"
)

const (
	grpcMDCLIConfig    = `/configure system grpc md-cli admin-state enable`
	profileMDCLIConfig = `/configure system security aaa local-profiles profile "administrative" grpc rpc-authorization md-cli-session permit`
	tls13CipherCCM8    = `/configure system security tls server-cipher-list "clab-all" tls13-cipher 5 name tls-aes128-ccm8-sha256`
)

func (n *sros) setVersionSpecificParams(tplData *srosTemplateData) {
	currVersion := tplData.SwVersion.MajorMinorSemverString()

	if semver.Compare(currVersion, "v26.0") < 0 {
		tplData.GRPCConfig += "\n" + grpcMDCLIConfig
		tplData.SystemConfig += "\n" + profileMDCLIConfig

		if tplData.IsSecureGrpc {
			tplData.GRPCConfig += "\n" + tls13CipherCCM8
		}
	}
}

// buildPKIImportXML builds the NETCONF action XML that imports a PEM file into the PKI store.
func buildPKIImportXML(inputURL, outputFile, importType string) string {
	action := etree.NewElement("action")
	action.CreateAttr("xmlns", "urn:ietf:params:xml:ns:yang:1")

	admin := action.CreateElement("admin")
	admin.CreateAttr("xmlns", "urn:nokia.com:sros:ns:yang:sr:oper-admin")

	importElem := admin.CreateElement("system").
		CreateElement("security").
		CreateElement("pki").
		CreateElement("import")

	// Add import parameters
	importElem.CreateElement("input-url").SetText(inputURL)
	importElem.CreateElement("output-file").SetText(outputFile)
	importElem.CreateElement("type").SetText(importType)
	importElem.CreateElement("format").SetText("pem")
	var buf bytes.Buffer
	action.WriteTo(&buf, &etree.WriteSettings{
		CanonicalText:    false,
		CanonicalAttrVal: false,
	})
	return buf.String()
}

// buildTLSProfileXML builds the TLS profile configuration XML.
func buildTLSProfileXML() string {
	config := etree.NewElement("config")
	configure := config.CreateElement("configure")
	configure.CreateAttr("xmlns", "urn:nokia.com:sros:ns:yang:sr:conf")
	configure.CreateAttr("xmlns:nc", "urn:ietf:params:xml:ns:netconf:base:1.0")

	certProfile := configure.CreateElement("system").
		CreateElement("security").
		CreateElement("tls").
		CreateElement("cert-profile")

	// Set operation attribute
	certProfile.CreateAttr("nc:operation", "merge")

	// Add profile configuration
	certProfile.CreateElement("cert-profile-name").SetText(tlsCertProfileName)
	certProfile.CreateElement("admin-state").SetText("enable")

	var buf bytes.Buffer
	config.WriteTo(&buf, &etree.WriteSettings{
		CanonicalText:    false,
		CanonicalAttrVal: false,
	})
	return buf.String()
}

// createSROSConfigFiles handles config generation for the SR-SIM kind.
// Flow: version detection → buildStartupConfig (default + partial) → GenerateConfig(dst, config).
func (n *sros) createSROSConfigFiles() error {
	// Get version from image before generating config
	if n.swVersion == nil {
		ctx := context.Background()
		version, err := n.srosVersionFromImage(ctx)
		if err != nil {
			n.swVersion = n.parseVersionString(srosDefaultVersion)
			log.Warn("Failed to get SR OS version from image",
				"node", n.Cfg.ShortName, "version", n.swVersion, "error", err)
		} else {
			n.swVersion = version
			log.Info("Retrieved SR OS version from image",
				"node", n.Cfg.ShortName,
				"version", fmt.Sprintf("%s.%s.%s", version.Major, version.Minor, version.Build))
		}
	}

	// Path pointing to the target config file under configCf3 dir
	cf3CfgFile := filepath.Join(
		n.Cfg.LabDir,
		n.Cfg.Env[envNokiaSrosSlot],
		configCf3,
		startupCfgName,
	)
	isPartial := clabutils.IsPartialConfigFile(n.Cfg.StartupConfig)

	// generate config and use that to boot node
	log.Debug("Reading startup-config", "node", n.Cfg.ShortName, "startup-config",
		n.Cfg.StartupConfig, "isPartial", isPartial)

	startupConfig, err := n.buildStartupConfig(isPartial)
	if err != nil {
		return err
	}

	if startupConfig == "" {
		log.Debug(
			"startup config is empty, skipping startup config file generation",
			"node",
			n.Cfg.ShortName,
		)
		return nil
	}

	return n.GenerateConfig(cf3CfgFile, startupConfig)
}

// buildStartupConfig returns the full startup config string: either from user file (full config)
// or from default + partial config generation. It does not return a template; the name is
// historical.
func (n *sros) buildStartupConfig(isPartial bool) (string, error) {
	// User provides full startup config
	if n.Cfg.StartupConfig != "" && !isPartial {
		c, err := os.ReadFile(n.Cfg.StartupConfig)
		if err != nil {
			return "", err
		}

		cBuf, err := clabutils.SubstituteEnvsAndTemplate(bytes.NewReader(c), n.Cfg)
		if err != nil {
			return "", err
		}
		return cBuf.String(), nil
	}

	// Generate default config and optionally add partial config
	if err := n.addDefaultConfig(); err != nil {
		return "", err
	}
	if err := n.addPartialConfig(); err != nil {
		return "", err
	}

	return string(n.startupCliCfg), nil
}

// prepareConfigTemplateData prepares all data needed for template selection and execution.
// Service configs are filled from a single table-driven result: variant → getFullSnippetSet(v).
func (n *sros) prepareConfigTemplateData() (*srosTemplateData, error) {
	b, err := n.banner()
	if err != nil {
		return nil, err
	}

	componentConfig := ""
	if !isFullConfigFile(n.Cfg.StartupConfig) {
		componentConfig = n.generateComponentConfig()
	} else {
		log.Debugf(
			"SR-SIM node %q has non-partial startup-config defined, skipping component config gen",
			n.Cfg.LongName,
		)
	}

	v := n.resolveConfigVariant()
	snippets := getFullSnippetSet(v)
	configMode := string(v.Mode)
	if v.ForceClassic {
		log.Warn(
			"SAR-Hm nodes only support classic configuration mode. Overriding configuration mode to 'classic'",
			"node",
			n.Cfg.LongName,
			"node-type",
			strings.ToLower(n.Cfg.NodeType),
		)
		configMode = string(ConfigModeClassic)
		n.kindSpecificCfg().ConfigMode = ConfigModeClassic
	}

	tplData := &srosTemplateData{
		// Selection criteria
		NodeType:          strings.ToLower(n.Cfg.NodeType),
		ConfigurationMode: configMode,
		SwVersion:         n.swVersion,
		IsSecureGrpc:      *n.Cfg.Certificate.Issue,

		// Node data
		Name:            n.Cfg.ShortName,
		TLSKey:          n.Cfg.TLSKey,
		TLSCert:         n.Cfg.TLSCert,
		TLSAnchor:       n.Cfg.TLSAnchor,
		Banner:          b,
		IFaces:          map[string]tplIFace{},
		MgmtMTU:         0,
		MgmtIPMTU:       n.Runtime.Mgmt().MTU,
		ComponentConfig: componentConfig,

		// Service configs from variant (single source of truth)
		SystemConfig:  snippets.SystemConfig,
		GRPCConfig:    snippets.GRPCConfig,
		SNMPConfig:    snippets.SNMPConfig,
		NetconfConfig: snippets.NetconfConfig,
		LoggingConfig: snippets.LoggingConfig,
		SSHConfig:     snippets.SSHConfig,
	}

	if n.Config().DNS != nil {
		tplData.DNSServers = append(tplData.DNSServers, n.Config().DNS.Servers...)
	}

	n.prepareSSHPubKeys(tplData)

	n.setVersionSpecificParams(tplData)

	return tplData, nil
}

// addDefaultConfig adds sros default configuration such as tls certs, gnmi/json-rpc, login-banner,
// ssh keys.
func (n *sros) addDefaultConfig() error {
	// Prepare all template data
	tplData, err := n.prepareConfigTemplateData()
	if err != nil {
		return err
	}

	// Select appropriate template
	srosCfgTpl, err := n.selectConfigTemplate(tplData)
	if err != nil {
		return fmt.Errorf("failed to select config template: %w", err)
	}
	log.Debug("Prepare SR OS config template", "template", srosCfgTpl.Name(),
		"node", n.Cfg.LongName,
		"configuration-mode", tplData.ConfigurationMode,
		"node-type", tplData.NodeType,
		"secure-grpc", tplData.IsSecureGrpc,
		"sw-version", tplData.SwVersion)

	// Execute template
	buf := new(bytes.Buffer)
	err = srosCfgTpl.Execute(buf, tplData)
	if err != nil {
		return err
	}

	if buf.Len() == 0 {
		log.Warn(
			"Buffer empty, template parsing error",
			"node", n.Cfg.ShortName,
			"template", srosCfgTpl.Name(),
		)
	} else {
		log.Debug("Additional default config parsed",
			"node", n.Cfg.ShortName,
			"template", srosCfgTpl.Name())
		n.startupCliCfg = append(n.startupCliCfg, buf.String()...)
	}

	return nil
}

// applyPartialConfig applies partial configuration to the SR OS.
func (n *sros) addPartialConfig() error {
	if n.Cfg.StartupConfig != "" {
		// b holds the configuration to be applied to the node
		b := &bytes.Buffer{}
		// apply partial configs if partial config is used
		if clabutils.IsPartialConfigFile(n.Cfg.StartupConfig) && n.isCPM("") {
			log.Info("Adding configuration",
				"node", n.Cfg.LongName,
				"type", "partial",
				"source", n.Cfg.StartupConfig)

			r, err := os.Open(n.Cfg.StartupConfig)
			if err != nil {
				return err
			}

			defer r.Close() // skipcq: GO-S2307

			_, err = io.Copy(b, r)
			if err != nil {
				return err
			}

			configContent, err := clabutils.SubstituteEnvsAndTemplate(b, n.Cfg)
			if err != nil {
				return err
			}
			if configContent.Len() == 0 {
				log.Warn(
					"Buffer empty, PARTIAL config template parsing error",
					"node",
					n.Cfg.ShortName,
				)
			} else {
				log.Debug("Additional PARTIAL config parsed", "node",
					n.Cfg.ShortName, "partial-config", configContent.String())
				n.startupCliCfg = append(n.startupCliCfg, configContent.String()...)
			}
		} else {
			log.Warn(
				"Passed startup-config option, but it will not have any effect",
				"node",
				n.Cfg.ShortName,
			)
		}
	}
	return nil
}

// isConfigClassic reports whether the node is in classic or mixed configuration mode.
func (n *sros) isConfigClassic() bool {
	mode := n.kindSpecificCfg().ConfigMode
	return mode == ConfigModeClassic || mode == ConfigModeMixed
}

// isFullConfigFile returns true if the config file doesn't contain .partial substring
// and the config file is NOT nil (ie. startup config IS defined).
// it is intended that the 'c' arg is n.Cfg.StartupConfig.
func isFullConfigFile(c string) bool {
	return c != "" && !clabutils.IsPartialConfigFile(c)
}

package sros

import (
	"context"
	"errors"
	"fmt"
	"maps"

	clabutils "github.com/srl-labs/containerlab/utils"

	clabconstants "github.com/srl-labs/containerlab/constants"
	clabnodes "github.com/srl-labs/containerlab/nodes"
	clabruntime "github.com/srl-labs/containerlab/runtime"
	clabtypes "github.com/srl-labs/containerlab/types"
	"github.com/vishvananda/netns"
)

// namespaceNode owns the shared network namespace of a components-based SR-SIM node.
type namespaceNode struct {
	clabnodes.DefaultNode
}

func (n *namespaceNode) Init(cfg *clabtypes.NodeConfig, opts ...clabnodes.NodeOption) error {
	n.DefaultNode = *clabnodes.NewDefaultNode(n)
	n.Cfg = cfg
	n.StopSignal = clabtypes.SIGTERM

	for _, o := range opts {
		o(n)
	}

	return nil
}

func (n *sros) newNetnsConfig() *clabtypes.NodeConfig {
	labels := maps.Clone(n.Cfg.Labels)

	if labels == nil {
		labels = map[string]string{}
	}

	shortName := fmt.Sprintf("%s-%s", n.Cfg.ShortName, "netns")
	labels[clabconstants.NodeName] = shortName

	longName := fmt.Sprintf("%s-%s", n.Cfg.LongName, "netns")
	labels[clabconstants.LongName] = longName

	labels[clabconstants.NodeType] = "srsim-netns"
	labels[clabconstants.InternalNode] = "true"

	// this node will be the root node
	labels[clabconstants.RootNodeName] = n.Cfg.ShortName
	labels[clabconstants.RootNodeLongName] = n.Cfg.LongName

	return &clabtypes.NodeConfig{
		ShortName:             shortName,
		LongName:              longName,
		LabDir:                n.Cfg.LabDir,
		Index:                 n.Cfg.Index,
		Kind:                  n.Cfg.Kind,
		NodeType:              "srsim-netns",
		Image:                 n.Cfg.Image,
		ImagePullPolicy:       n.Cfg.ImagePullPolicy,
		RestartPolicy:         n.Cfg.RestartPolicy,
		Sysctls:               maps.Clone(n.Cfg.Sysctls),
		User:                  "0:0",
		Entrypoint:            "/bin/sh",
		Cmd:                   `-c "trap 'exit 0' TERM INT; sleep infinity & wait $!"`,
		Env:                   map[string]string{},
		PortBindings:          n.Cfg.PortBindings,
		PortSet:               n.Cfg.PortSet,
		NetworkMode:           n.Cfg.NetworkMode,
		MgmtNet:               n.Cfg.MgmtNet,
		MgmtIntf:              n.Cfg.MgmtIntf,
		MgmtIPv4Address:       n.Cfg.MgmtIPv4Address,
		MgmtIPv4AddressAuto:   n.Cfg.MgmtIPv4AddressAuto,
		MgmtIPv4PrefixLength:  n.Cfg.MgmtIPv4PrefixLength,
		MgmtIPv6Address:       n.Cfg.MgmtIPv6Address,
		MgmtIPv6AddressAuto:   n.Cfg.MgmtIPv6AddressAuto,
		MgmtIPv6PrefixLength:  n.Cfg.MgmtIPv6PrefixLength,
		MgmtIPv4Gateway:       n.Cfg.MgmtIPv4Gateway,
		MgmtIPv6Gateway:       n.Cfg.MgmtIPv6Gateway,
		MacAddress:            n.Cfg.MacAddress,
		Aliases:               n.Cfg.Aliases,
		DNS:                   n.Cfg.DNS,
		ExtraHosts:            n.Cfg.ExtraHosts,
		Labels:                labels,
		Runtime:               n.Cfg.Runtime,
		ResultingPortBindings: n.Cfg.ResultingPortBindings,
	}
}

func (n *sros) ensureNetnsRunning(ctx context.Context) error {
	switch status := n.netnsNode.GetContainerStatus(ctx); status {
	case clabruntime.Running:
		// The namespace holder intentionally survives regular node lifecycle operations.
	case clabruntime.Created, clabruntime.Stopped:
		if err := n.netnsNode.Start(ctx); err != nil {
			return fmt.Errorf("node %q network namespace container start error: %w",
				n.Cfg.ShortName, err)
		}
	case clabruntime.Paused:
		if err := n.Runtime.UnpauseContainer(ctx, n.netnsNode.Config().LongName); err != nil {
			return fmt.Errorf("node %q network namespace container unpause error: %w",
				n.Cfg.ShortName, err)
		}
	case clabruntime.NotFound:
		return fmt.Errorf(
			"node %q network namespace container %q not found; recreate the node",
			n.Cfg.ShortName, n.netnsNode.Config().LongName,
		)
	default:
		return fmt.Errorf("node %q network namespace container %q is %s",
			n.Cfg.ShortName, n.netnsNode.Config().LongName, status)
	}

	return nil
}

func (n *sros) cleanupParkingNetNS() error {
	name := clabutils.ParkingNetnsName(n.Cfg.LongName)
	if _, err := clabutils.GetNamedNetNS(name); err != nil {
		return nil
	}

	return netns.DeleteNamed(name)
}

// GetNSPath retrieves the Namespace Path.
func (n *sros) GetNSPath(ctx context.Context) (string, error) {
	if n.isStandaloneNode() || (n.isDistributedCardNode() && n.rootCtrName == "") {
		return n.DefaultNode.GetNSPath(ctx)
	} else if n.isDistributedCardNode() {
		return n.Runtime.GetNSPath(ctx, n.rootCtrName)
	}
	return n.netnsNode.GetNSPath(ctx)
}

// DeleteNetnsSymlink deletes the symlink file created for the container netns.
func (n *sros) DeleteNetnsSymlink() error {
	var errs []error

	// if it is the base node, then we need to delete the symlink for all the components.
	if n.isDistributedBaseNode() {
		for _, componentNode := range n.componentNodes {
			errs = append(errs, componentNode.DeleteNetnsSymlink())
		}
		if n.netnsNode != nil {
			errs = append(errs, n.netnsNode.DeleteNetnsSymlink())
		}
		errs = append(errs, clabutils.DeleteNetnsSymlink(n.Cfg.LongName))
	}

	errs = append(errs, n.DefaultNode.DeleteNetnsSymlink(), n.cleanupParkingNetNS())

	return errors.Join(errs...)
}

